#!/usr/bin/env python3
"""dashboard.py - live ZeroZeta project dashboard for the spec-driven build kit.   VERSION: v1

Shows, in plain language, what is done, what is being built right now, what is ahead,
and what needs you. Refreshes every few seconds. Works on a phone. Python standard library only.

  python3 scripts/dashboard.py                 this computer only: http://localhost:8765
  python3 scripts/dashboard.py --lan           also phones on your Wi-Fi or Tailscale (a PIN is required)
  python3 scripts/dashboard.py --read-only     watch only: no buttons that change anything
  options: --port 8765  --pin 123456 (else a random PIN is printed)

Reads: docs/TASKS.md, docs/plans/, docs/reviews/, git, GitHub (gh, if logged in),
.kit/events.jsonl (written by loop.sh, gate.sh, pr.sh, start.sh, autopilot.sh) and .autopilot/.
Buttons run only the kit's own scripts (approve a plan, build, open or merge a PR, start the next
feature, run the checks, summarise). Writing code, `review` and `explain` stay in Claude.
"""
from __future__ import annotations

import argparse
import base64
import datetime as dt
import glob
import http.server
import json
import os
import re
import secrets
import shutil
import socket
import subprocess
import threading
import time
import urllib.parse

VERSION = "v1"
LOGO_PNG = base64.b64decode("")
ICON_PNG = base64.b64decode("")
STATIONS = ["Plan", "Approved", "Building", "Checking", "Your review", "Live"]
ID_RE = re.compile(r"(REQ|BUG)-\d{3}")
TASK_RE = re.compile(r"^\s*- \[( |x|X)\] (REQ-\d{3}) \(#(\d+)\)\s*(.*)$")
SPEC_DOCS = [
    ("00-idea.md", "Idea"), ("01-prd.md", "Requirements (PRD)"), ("02-architecture.md", "Architecture"),
    ("03-ui-design.md", "UI design"), ("04-testplan.md", "Test plan"), ("TASKS.md", "Task list"),
    ("RULES.md", "Rules"), ("05-launch-checklist.md", "Launch checklist"),
]


# ---------------------------------------------------------------- helpers
def find_root() -> str:
    """Return the git repo root (or the current folder)."""
    try:
        out = subprocess.run(["git", "rev-parse", "--show-toplevel"], capture_output=True, text=True, timeout=5)
        if out.returncode == 0:
            return out.stdout.strip()
    except (OSError, subprocess.SubprocessError):
        pass
    return os.getcwd()


ROOT = find_root()


def run(cmd: list[str], timeout: int = 20) -> tuple[int, str]:
    """Run a command in the repo root; return (exit code, stdout)."""
    try:
        p = subprocess.run(cmd, cwd=ROOT, capture_output=True, text=True, timeout=timeout)
        return p.returncode, p.stdout
    except (OSError, subprocess.SubprocessError):
        return 1, ""


def git(*args: str) -> str:
    """Return git output, or '' on error."""
    return run(["git", *args])[1].strip()


def read(path: str) -> str:
    """Return a repo file's text, or ''."""
    try:
        with open(os.path.join(ROOT, path), encoding="utf-8", errors="replace") as f:
            return f.read()
    except OSError:
        return ""


def first_line(path: str) -> str:
    """Return the first non-blank line of a repo file, or ''."""
    for line in read(path).splitlines():
        if line.strip():
            return line.strip()
    return ""


def base_ref() -> str:
    """Return origin/main, main, origin/master or master: whichever exists."""
    for ref in ("origin/main", "main", "origin/master", "master"):
        if run(["git", "rev-parse", "--verify", "-q", ref])[0] == 0:
            return ref
    return "HEAD"


def pid_alive(pid: int) -> bool:
    """True if a process with this id is running."""
    try:
        os.kill(pid, 0)
        return True
    except (OSError, ValueError):
        return False


class GhCache:
    """GitHub Issues and PRs through gh, refreshed at most once a minute."""

    def __init__(self) -> None:
        self.ok = bool(shutil.which("gh")) and run(["gh", "auth", "status"], 10)[0] == 0
        self.at = 0.0
        self.issues: dict[int, dict] = {}
        self.prs: list[dict] = []
        self.repo_url = ""

    def refresh(self) -> None:
        if not self.ok or time.time() - self.at < 60:
            return
        self.at = time.time()
        code, out = run(["gh", "issue", "list", "--state", "all", "--limit", "300", "--json", "number,state,title"], 30)
        if code == 0:
            self.issues = {i["number"]: i for i in json.loads(out or "[]")}
        code, out = run(["gh", "pr", "list", "--state", "all", "--limit", "100",
                         "--json", "number,state,headRefName,title,url"], 30)
        if code == 0:
            self.prs = json.loads(out or "[]")
        code, out = run(["gh", "repo", "view", "--json", "url", "--jq", ".url"], 15)
        if code == 0:
            self.repo_url = out.strip()

    def pr_for(self, rid: str) -> dict | None:
        for pr in self.prs:  # newest first
            if rid in pr.get("headRefName", "") or rid in pr.get("title", ""):
                return pr
        return None


GH = GhCache()


# ---------------------------------------------------------------- events and jobs
def load_events(limit: int = 400) -> list[dict]:
    """Return the newest events from .kit/events.jsonl (oldest first)."""
    lines = read(".kit/events.jsonl").splitlines()[-limit:]
    out = []
    for line in lines:
        try:
            out.append(json.loads(line))
        except ValueError:
            continue
    return out


class Jobs:
    """One kit script at a time, started from the dashboard, output kept in .kit/jobs/."""

    def __init__(self) -> None:
        self.lock = threading.Lock()
        self.current: dict | None = None

    def busy(self) -> bool:
        return bool(self.current and self.current.get("running"))

    def start(self, name: str, label: str, cmd: list[str], env: dict | None = None) -> str:
        with self.lock:
            if self.busy():
                return "Another action is still running: " + self.current["label"]
            os.makedirs(os.path.join(ROOT, ".kit", "jobs"), exist_ok=True)
            log = os.path.join(ROOT, ".kit", "jobs", f"{time.strftime('%Y%m%d-%H%M%S')}-{name}.log")
            self.current = {"name": name, "label": label, "running": True, "rc": None, "log": log,
                            "started": time.time()}
            threading.Thread(target=self._run, args=(cmd, env, log), daemon=True).start()
            return ""

    def _run(self, cmd: list[str], env: dict | None, log: str) -> None:
        full_env = dict(os.environ, **(env or {}))
        with open(log, "w", encoding="utf-8") as f:
            try:
                rc = subprocess.run(cmd, cwd=ROOT, stdout=f, stderr=subprocess.STDOUT, env=full_env,
                                    stdin=subprocess.DEVNULL).returncode
            except OSError as e:
                f.write(f"could not start: {e}\n")
                rc = 1
        with self.lock:
            if self.current:
                self.current.update(running=False, rc=rc, ended=time.time())

    def view(self) -> dict | None:
        if not self.current:
            return None
        c = dict(self.current)
        try:
            with open(c["log"], encoding="utf-8", errors="replace") as f:
                tail = f.read().splitlines()[-14:]
        except OSError:
            tail = []
        c["tail"] = [re.sub(r"\x1b\[[0-9;]*m", "", t) for t in tail]
        c.pop("log", None)
        return c


JOBS = Jobs()


# ---------------------------------------------------------------- state
def current_id() -> str:
    m = ID_RE.search(git("branch", "--show-current"))
    return m.group(0) if m else ""


def read_for(rid: str, path: str, ctx: dict) -> str:
    """Read a file as it is on the feature's own branch (plans and reviews live there until merge)."""
    if ctx["cur_id"] == rid or rid not in ctx["branches"]:
        return read(path)
    return run(["git", "show", f"{ctx['branches'][rid]}:{path}"])[1]


def head_line(text: str) -> str:
    """First non-blank line of a text."""
    return next((ln.strip() for ln in text.splitlines() if ln.strip()), "")


def feature_state(rid: str, issue: int, title: str, ticked: bool, ctx: dict) -> dict:
    """Work out where one feature is on the journey and what (if anything) it needs."""
    plan = head_line(read_for(rid, f"docs/plans/{rid}.md", ctx))
    review_text = read_for(rid, f"docs/reviews/{rid}.md", ctx)
    review = head_line(review_text)
    walkthrough = "## Walkthrough" in review_text
    pr = GH.pr_for(rid)
    issue_closed = GH.issues.get(issue, {}).get("state") == "CLOSED"
    on_branch = ctx["cur_id"] == rid
    loop = ctx["loops"].get(rid)
    st = {"id": rid, "issue": issue, "title": title, "stage": -1, "status": "Not started yet",
          "needs": None, "running": bool(loop), "current": on_branch,
          "pr_url": pr.get("url") if pr else "", "has_plan": bool(plan), "has_review": bool(review)}

    if rid in ctx["merged"] or ticked or issue_closed or (pr and pr["state"] == "MERGED"):
        st.update(stage=5, status="Live")
    elif pr and pr["state"] == "OPEN":
        st.update(stage=4, status="Waiting for your review on GitHub")
        st["needs"] = {"text": "Review the pull request, then merge it", "action": "merge_pr",
                       "label": "Merge", "confirm": "I have read the review, the walkthrough and the changes",
                       "link": pr.get("url", ""), "branch_only": True}
    elif review.startswith("Verdict: APPROVE"):
        st.update(stage=3, status="Checked by the reviewer: approved")
        if not walkthrough:
            st["needs"] = {"text": "Ask Claude for the walkthrough: type  explain", "claude": "explain",
                           "doc": "review"}
        else:
            st["needs"] = {"text": "Open it for your review", "action": "open_pr", "label": "Open for review",
                           "doc": "review", "branch_only": True}
    elif loop:
        st.update(stage=2, status=loop["msg"])
    elif review.startswith("Verdict: CHANGES REQUESTED"):
        st.update(stage=2, status="The reviewer asked for changes")
        st["needs"] = {"text": "Build again: the loop fixes the reviewer's findings", "action": "run_loop",
                       "label": "Fix and rebuild", "doc": "review", "branch_only": True}
    elif plan.startswith("Status: APPROVED"):
        ahead = ctx["ahead"].get(rid, 0)
        if ahead > 0 and ctx["last_loop"].get(rid) == "green":
            st.update(stage=3, status="Built; waiting for the reviewer")
            st["needs"] = {"text": "Ask Claude to check it: type  review", "claude": "review"}
        elif ahead > 0:
            st.update(stage=2, status="Partly built")
            st["needs"] = {"text": "Continue building", "action": "run_loop", "label": "Build",
                           "branch_only": True}
            if ctx["last_loop"].get(rid) == "cap":
                st["needs"] = {"text": "Building stopped at its limit: the plan needs rework. "
                                       "In Claude: next (re-plan), then approve again", "claude": "next",
                               "doc": "plan"}
        else:
            st.update(stage=1, status="Plan approved, ready to build")
            st["needs"] = {"text": "Start building", "action": "run_loop", "label": "Build",
                           "doc": "plan", "branch_only": True}
    elif plan.startswith("Status: DRAFT"):
        st.update(stage=0, status="Plan written, waiting for your approval")
        st["needs"] = {"text": "Read the plan and approve it", "action": "approve_plan",
                       "label": "Read and approve", "doc": "plan", "branch_only": True}
    elif on_branch:
        st.update(stage=0, status="Started: the plan is next")
        st["needs"] = {"text": "Ask Claude for the plan: type  next", "claude": "next"}
    if st["needs"] and st["needs"].get("branch_only") and not on_branch:
        st["needs"]["switch"] = True
    return st


def running_loops(events: list[dict]) -> tuple[dict, dict]:
    """Return ({id: latest event} for loops still running, {id: last loop result})."""
    started: dict[int, dict] = {}
    last_result: dict[str, str] = {}
    latest: dict[int, dict] = {}
    for e in events:
        pid = e.get("pid")
        if e.get("kind") == "loop_start" and pid:
            started[pid] = e
        if pid in started:
            latest[pid] = e
        if e.get("kind") == "loop_end":
            last_result[e.get("id", "")] = e.get("result", "")
            started.pop(pid, None)
    loops = {}
    for pid, e in started.items():
        if pid_alive(pid):
            loops[e.get("id", "")] = latest.get(pid, e)
    return loops, last_result


def autopilot_state(events: list[dict]) -> dict:
    """Is autopilot running, and what did its last report say needs you?"""
    run_e = None
    for e in events:
        if e.get("kind") == "autopilot_start":
            run_e = e
        elif e.get("kind") == "autopilot_end" and run_e and e.get("pid") == run_e.get("pid"):
            run_e = None
    running = bool(run_e and pid_alive(run_e.get("pid", 0)))
    needs: list[str] = []
    reports = sorted(glob.glob(os.path.join(ROOT, ".autopilot", "*.md")))
    if reports:
        txt = open(reports[-1], encoding="utf-8", errors="replace").read()
        part = txt.split("## Needs you", 1)[1] if "## Needs you" in txt else ""
        needs = [ln[2:].replace("**", "") for ln in part.splitlines() if ln.startswith("- ")][:6]
    last = next((e for e in reversed(events) if e.get("src") == "autopilot"), None)
    return {"running": running, "needs": needs, "last": last["msg"] if (running and last) else ""}


def build_state() -> dict:
    """Everything the page shows, in one JSON document."""
    GH.refresh()
    events = load_events()
    loops, last_loop = running_loops(events)
    base = base_ref()
    log = git("log", base, "--oneline", "-E", "--grep", r"(feat|fix)\((REQ|BUG)-[0-9]{3}\)")
    merged = set(re.findall(r"(?:feat|fix)\(((?:REQ|BUG)-\d{3})\)", log))
    ahead: dict[str, int] = {}
    branches: dict[str, str] = {}
    for br in git("branch", "--format=%(refname:short)").splitlines():
        m = ID_RE.search(br)
        if m:
            branches[m.group(0)] = br
            n = git("rev-list", "--count", f"{base}..{br}", "--", ".", ":(exclude)docs")  # code commits only
            ahead[m.group(0)] = int(n) if n.isdigit() else 0
    ctx = {"cur_id": current_id(), "loops": loops, "last_loop": last_loop, "merged": merged, "ahead": ahead,
           "branches": branches}

    tasks_txt = read("docs/TASKS.md")
    tasks_template = tasks_txt.startswith("Status: TEMPLATE")
    features = []
    if not tasks_template:
        for line in tasks_txt.splitlines():
            m = TASK_RE.match(line)
            if m:
                features.append(feature_state(m.group(2), int(m.group(3)), m.group(4).strip() or m.group(2),
                                              m.group(1).lower() == "x", ctx))
    if ctx["cur_id"].startswith("BUG-"):
        bid = ctx["cur_id"]
        issue = next((n for n, i in GH.issues.items() if i["title"].startswith(bid)), 0)
        title = GH.issues.get(issue, {}).get("title", bid).split(":", 1)[-1].strip()
        features.insert(0, feature_state(bid, issue, "Bug fix: " + title, False, ctx))

    spec = []
    for fname, label in SPEC_DOCS:
        s = first_line(f"docs/{fname}")
        state = "approved" if s.startswith("Status: APPROVED") else "draft" if s.startswith("Status: DRAFT") \
            else "template" if s.startswith("Status: TEMPLATE") else "missing"
        spec.append({"label": label, "state": state})

    gate = next((e for e in reversed(events) if e.get("kind") == "gate"), None)
    today = dt.date.today().isoformat()
    cost = sum(float(e.get("cost") or 0) for e in events if str(e.get("ts", "")).startswith(today)
               and e.get("kind") == "check")
    ap = autopilot_state(events)
    live = sum(1 for f in features if f["stage"] == 5)

    needs = [dict(f["needs"], id=f["id"], title=f["title"]) for f in features
             if f["needs"] and f["stage"] < 5]
    needs.sort(key=lambda n: (not n.get("action") or n.get("switch", False), n["id"]))
    for line in ap["needs"]:
        needs.append({"id": "", "title": "Autopilot", "text": line})
    if any(s["state"] != "approved" for s in spec[:6]):
        needs.insert(0, {"id": "", "title": "Specification", "claude": "setup",
                         "text": "Finish the specification with Claude: type  setup"})
    if not needs and not loops and not JOBS.busy() and any(f["stage"] < 0 for f in features) \
            and not any(0 <= f["stage"] < 5 for f in features if f["current"]):
        nxt = next(f for f in features if f["stage"] < 0)
        needs.append({"id": nxt["id"], "title": nxt["title"], "text": "Start the next feature",
                      "action": "start_next", "label": "Start"})

    now = {"kind": "idle", "text": "Nothing is running right now."}
    job = JOBS.view()
    if job and job["running"]:
        now = {"kind": "job", "text": job["label"], "tail": job["tail"]}
    elif loops:
        rid, e = next(iter(loops.items()))
        f = next((x for x in features if x["id"] == rid), {"title": rid})
        now = {"kind": "loop", "id": rid, "title": f["title"], "text": e.get("msg", "Building"),
               "iter": e.get("iter"), "max": e.get("max")}
    elif ap["running"]:
        now = {"kind": "autopilot", "text": ap["last"] or "Autopilot is working"}
    elif needs:
        now["next"] = needs[0]["text"]

    title = ""
    for line in read("docs/01-prd.md").splitlines()[:6]:
        if line.startswith("# ") and "<" not in line:
            title = line[2:].split(" - ")[0].strip()
    summary = read(".kit/summary.txt").strip()
    return {
        "project": title or os.path.basename(ROOT), "branch": git("branch", "--show-current"),
        "features": features, "live": live, "total": len(features), "needs": needs, "now": now,
        "events": [{"ts": e.get("ts", ""), "kind": e.get("kind", ""), "id": e.get("id", ""), "msg": e.get("msg", "")}
                   for e in events[-30:]][::-1],
        "gate": {"ok": gate.get("ok"), "msg": gate.get("msg"), "ts": gate.get("ts")} if gate else None,
        "cost_today": round(cost, 2), "spec": spec, "spec_done": not any(s["state"] != "approved" for s in spec[:6]),
        "job": job, "gh": GH.ok, "repo_url": GH.repo_url, "summary": summary,
        "read_only": ARGS.read_only, "version": VERSION, "server_time": time.time(),
    }


# ---------------------------------------------------------------- actions
def act(action: str, rid: str) -> tuple[bool, str]:
    """Run one allow-listed action. Returns (ok, message)."""
    if ARGS.read_only:
        return False, "This dashboard is read-only."
    if rid and not re.fullmatch(r"(REQ|BUG)-\d{3}", rid):
        return False, "Unknown feature."
    cur = current_id()
    if action in {"approve_plan", "run_loop", "open_pr", "merge_pr"} and rid != cur:
        return False, f"{rid} is not the feature checked out right now ({cur or 'none'}). Use Switch first."
    if action == "approve_plan":
        path = os.path.join(ROOT, "docs", "plans", f"{rid}.md")
        text = read(f"docs/plans/{rid}.md")
        if not text.startswith("Status: DRAFT"):
            return False, "The plan is not a draft waiting for approval."
        lines = text.split("\n")
        lines[0] = f"Status: APPROVED - {dt.date.today().isoformat()} (dashboard)"
        with open(path, "w", encoding="utf-8") as f:
            f.write("\n".join(lines))
        issue = next((m.group(3) for m in map(TASK_RE.match, read("docs/TASKS.md").splitlines())
                      if m and m.group(2) == rid), "")
        msg = f"docs({rid}): approved plan" + (f" (#{issue})" if issue else "")
        run(["git", "add", f"docs/plans/{rid}.md"])
        code, _ = run(["git", "commit", "-q", "-m", msg])
        record("plan_approved", rid, "Plan approved from the dashboard")
        return True, "Plan approved and committed." if code == 0 else "Plan approved (commit it in the git pane)."
    jobs = {
        "run_loop": ("loop", f"Building {rid}", ["bash", "scripts/loop.sh"], None),
        "open_pr": ("pr", f"Opening {rid} for your review", ["bash", "scripts/pr.sh"], None),
        "merge_pr": ("merge", f"Merging {rid} and running the after-merge checks",
                     ["bash", "scripts/pr.sh", "merge"], {"YES": "1"}),
        "start_next": ("start", "Starting the next feature", ["bash", "scripts/start.sh"], None),
        "switch": ("switch", f"Switching to {rid}", ["bash", "scripts/start.sh", rid], {"FORCE": "1"}),
        "run_gate": ("gate", "Running the quality checks", ["bash", "scripts/gate.sh"], None),
    }
    if action == "summarise":
        if not shutil.which("claude"):
            return False, "Claude Code is not on PATH here."
        evts = "\n".join(f"{e.get('ts', '')[:16]} {e.get('id', '')} {e.get('msg', '')}" for e in load_events(60))
        prompt = ("You explain software progress to a non-technical project owner. In at most 4 short sentences "
                  "of plain English, say what was done recently, what is happening now, and what needs the owner. "
                  "No jargon, no IDs unless needed. Events (oldest first):\n" + evts)
        err = JOBS.start("summary", "Writing a plain-English summary",
                         ["bash", "-c", 'claude -p "$ZZ_PROMPT" --model haiku > .kit/summary.txt'],
                         {"ZZ_PROMPT": prompt})
        return (not err), err or "Summary is being written."
    if action not in jobs:
        return False, "Unknown action."
    building = running_loops(load_events())[0]
    if action == "run_loop" and rid in building:
        return False, "It is already building."
    if action in {"switch", "start_next", "merge_pr"} and building:
        return False, "Wait until the current build finishes (see Right now)."
    name, label, cmd, env = jobs[action]
    err = JOBS.start(name, label, cmd, env)
    if not err:
        record("dashboard", rid, f"From the dashboard: {label.lower()}")
    return (not err), err or label + "..."


def record(kind: str, rid: str, msg: str) -> None:
    """Append an event like the shell scripts do."""
    os.makedirs(os.path.join(ROOT, ".kit"), exist_ok=True)
    e = {"ts": time.strftime("%Y-%m-%dT%H:%M:%S%z"), "src": "dashboard", "kind": kind, "id": rid, "msg": msg}
    with open(os.path.join(ROOT, ".kit", "events.jsonl"), "a", encoding="utf-8") as f:
        f.write(json.dumps(e) + "\n")


# ---------------------------------------------------------------- web server
SESSIONS: set[str] = set()
FAILS: dict[str, list[float]] = {}


class Handler(http.server.BaseHTTPRequestHandler):
    server_version = "ZeroZetaDashboard/" + VERSION

    def log_message(self, fmt: str, *args) -> None:  # quiet
        return

    def _send(self, code: int, body: bytes, ctype: str, extra: dict | None = None) -> None:
        self.send_response(code)
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "no-store")
        self.send_header("X-Content-Type-Options", "nosniff")
        self.send_header("X-Frame-Options", "DENY")
        self.send_header("Referrer-Policy", "no-referrer")
        for k, v in (extra or {}).items():
            self.send_header(k, v)
        self.end_headers()
        self.wfile.write(body)

    def _json(self, code: int, obj: dict, extra: dict | None = None) -> None:
        self._send(code, json.dumps(obj).encode(), "application/json", extra)

    def _authed(self) -> bool:
        if not ARGS.lan:
            return True
        cookie = self.headers.get("Cookie", "")
        m = re.search(r"zz_session=([A-Za-z0-9_\-]+)", cookie)
        return bool(m and m.group(1) in SESSIONS)

    def do_GET(self) -> None:
        path = urllib.parse.urlparse(self.path).path
        if path in ("/", "/index.html"):
            self._send(200, PAGE.encode(), "text/html; charset=utf-8")
        elif path == "/logo.png":
            self._send(200, LOGO_PNG, "image/png", {"Cache-Control": "max-age=86400"})
        elif path in ("/icon.png", "/apple-touch-icon.png", "/favicon.ico"):
            self._send(200, ICON_PNG, "image/png", {"Cache-Control": "max-age=86400"})
        elif path == "/manifest.json":
            self._json(200, {"name": "ZeroZeta build dashboard", "short_name": "Build", "start_url": "/",
                             "display": "standalone", "background_color": "#FFFFFF", "theme_color": "#1A8B5E",
                             "icons": [{"src": "/icon.png", "sizes": "180x180", "type": "image/png"}]})
        elif path == "/api/state":
            if not self._authed():
                self._json(401, {"error": "pin"})
                return
            self._json(200, build_state())
        elif path == "/api/doc":
            if not self._authed():
                self._json(401, {"error": "pin"})
                return
            q = urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query)
            rid, kind = q.get("id", [""])[0], q.get("kind", [""])[0]
            if not re.fullmatch(r"(REQ|BUG)-\d{3}", rid) or kind not in ("plan", "review"):
                self._json(400, {"error": "bad request"})
                return
            folder = "plans" if kind == "plan" else "reviews"
            ctx = {"cur_id": current_id(), "branches": {m.group(0): br for br in
                   git("branch", "--format=%(refname:short)").splitlines() for m in [ID_RE.search(br)] if m}}
            self._json(200, {"id": rid, "kind": kind, "text": read_for(rid, f"docs/{folder}/{rid}.md", ctx)})
        else:
            self._send(404, b"not found", "text/plain")

    def do_POST(self) -> None:
        path = urllib.parse.urlparse(self.path).path
        if self.headers.get("X-ZZ") != "1":
            self._json(403, {"error": "forbidden"})
            return
        try:
            n = min(int(self.headers.get("Content-Length", "0")), 4096)
            body = json.loads(self.rfile.read(n) or b"{}")
        except ValueError:
            self._json(400, {"error": "bad json"})
            return
        ip = self.client_address[0]
        if path == "/api/login":
            recent = [t for t in FAILS.get(ip, []) if time.time() - t < 900]
            FAILS[ip] = recent
            if len(recent) >= 5:
                self._json(429, {"error": "Too many wrong PINs. Wait 15 minutes."})
                return
            if secrets.compare_digest(str(body.get("pin", "")), ARGS.pin):
                tok = secrets.token_urlsafe(24)
                SESSIONS.add(tok)
                self._json(200, {"ok": True}, {"Set-Cookie": f"zz_session={tok}; HttpOnly; SameSite=Strict; "
                                                             "Path=/; Max-Age=2592000"})
            else:
                FAILS[ip].append(time.time())
                self._json(403, {"error": "Wrong PIN."})
            return
        if path == "/api/action":
            if not self._authed():
                self._json(401, {"error": "pin"})
                return
            ok, msg = act(str(body.get("action", "")), str(body.get("id", "")))
            self._json(200 if ok else 409, {"ok": ok, "msg": msg})
            return
        self._json(404, {"error": "not found"})


def addresses() -> list[str]:
    """Addresses a phone could use: LAN IPs and the Tailscale IP."""
    ips: list[str] = []
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s.connect(("10.255.255.255", 1))
        ips.append(s.getsockname()[0])
        s.close()
    except OSError:
        pass
    if shutil.which("tailscale"):
        code, out = run(["tailscale", "ip", "-4"], 5)
        if code == 0 and out.strip():
            ips.append(out.strip().splitlines()[0] + "  (Tailscale: works away from home)")
    return ips


def main() -> None:
    global ARGS
    p = argparse.ArgumentParser(description="Live ZeroZeta project dashboard")
    p.add_argument("--port", type=int, default=8765)
    p.add_argument("--lan", action="store_true", help="listen on all interfaces (phones); requires the PIN")
    p.add_argument("--pin", default="", help="6-digit PIN for --lan (default: random)")
    p.add_argument("--read-only", action="store_true", help="no buttons that change anything")
    ARGS = p.parse_args()
    ARGS.pin = ARGS.pin or f"{secrets.randbelow(10**6):06d}"
    host = "0.0.0.0" if ARGS.lan else "127.0.0.1"
    try:
        srv = http.server.ThreadingHTTPServer((host, ARGS.port), Handler)
    except OSError:
        print(f"  Port {ARGS.port} is busy: the dashboard is probably already running. "
              f"Open http://localhost:{ARGS.port}, or use --port 8766.")
        raise SystemExit(1)
    print(f"\n  ZeroZeta build dashboard {VERSION} - {os.path.basename(ROOT)}")
    print(f"  On this computer : http://localhost:{ARGS.port}")
    if ARGS.lan:
        for ip in addresses():
            addr, _, note = ip.partition("  ")
            print(f"  On your phone    : http://{addr}:{ARGS.port}  {note}")
        print(f"  PIN              : {ARGS.pin}")
        if "microsoft" in read("/proc/version").lower():
            print("  WSL note         : if the phone cannot connect, see runbook Phase 2e (mirrored networking).")
    else:
        print("  Phone access     : restart with --lan (see runbook Phase 2e)")
    print(f"  Mode             : {'read-only' if ARGS.read_only else 'watch and act'}   Stop with Ctrl-C\n")
    try:
        srv.serve_forever()
    except KeyboardInterrupt:
        print("\n  dashboard stopped")


